operations.new:
my $generator = OpenSSL::GenTemplate->new(%opts);
my $foundation_library_profile =
    ($generator->{config}->{target} // '') eq 'VC-FOUNDATION-AMD64-STATIC-NOASM-V1';
if ($foundation_library_profile) {
    foreach my $feature (qw(shared asm uplink apps docs tests module makedepend)) {
        die "Foundation library profile requires no-$feature\n"
            unless $generator->{disabled}->{$feature};
    }
    die "Foundation library profile requires reviewed raw-target closure\n"
        if @{$generator->{info}->{targets} // []};
}

# Build mandatory header file generators
foreach (@{$generator->{info}->{depends}->{""}}) { $generator->dogenerate($_); }

# Preserve recursive library and mandatory generation, without emitting
# optional programs, modules, installable scripts or documentation recipes.
if ($foundation_library_profile) {
    foreach (@{$generator->{info}->{libraries}}) { $generator->dolib($_); }
    return;
}

my $script = $self->{info}->{generate}->{$src}->[0];
if (($self->{config}->{target} // '') eq 'VC-FOUNDATION-AMD64-STATIC-NOASM-V1') {
    die "Foundation library profile rejects generated assembler: $src\n"
        if $src =~ /\.[sS]$/;
    die "Foundation library profile requires native generator review: $script\n"
        if grep { $_ eq $script } @{$self->{info}->{programs} // []};
    if ($script !~ /\.in$/) {
        require File::Spec;
        my $build_base = File::Spec->rel2abs($self->{config}->{builddir});
        my $normalized_script = File::Spec->abs2rel(
            File::Spec->rel2abs($script, $build_base), $build_base);
        my $allowed_script = File::Spec->abs2rel(
            File::Spec->rel2abs(
                File::Spec->catfile($self->{config}->{sourcedir},
                                    'util', 'mkbuildinf.pl'),
                $build_base),
            $build_base);
        die "Foundation library profile rejects unreviewed child script: $script\n"
            unless $normalized_script eq $allowed_script;
    }
}

my @srcs = @{$self->{info}->{sources}->{$obj}};
if (($self->{config}->{target} // '') eq 'VC-FOUNDATION-AMD64-STATIC-NOASM-V1') {
    die "Foundation library profile rejects non-C object source: $obj\n"
        if grep { !/\.c$/ } @srcs;
}

