operations.new:
 our @generated;
 if ($config{target} eq 'VC-FOUNDATION-AMD64-STATIC-NOASM-V1') {
     foreach my $feature (qw(shared asm uplink apps docs tests module makedepend)) {
         die "Foundation library profile requires no-$feature\n"
             unless $disabled{$feature};
     }
     # Exact build_libs uses mandatory prerequisites and recursively emitted
     # library generators. The maintained gentemplate guard rejects generated
     # assembler and native executable generators before emitting recipes.
     @generated = ();
 } else {
my %generatables =
    map { $_ => 1 }
    ( # The sources of stuff may be generated
        ( map { @{$unified_info{sources}->{$_}} }
              keys %{$unified_info{sources}} ),
        $disabled{shared}
            ? ()
            : ( map { @{$unified_info{shared_sources}->{$_}} }
                keys %{$unified_info{shared_sources}} ),
        # Things we explicitly depend on are usually generated
        ( map { $_ eq "" ? () : @{$unified_info{depends}->{$_}} }
              keys %{$unified_info{depends}} ));
@generated =
    sort ( ( grep { defined $unified_info{generate}->{$_} }
             sort keys %generatables ),
           # Scripts are assumed to be generated, so add them too
           ( grep { defined $unified_info{sources}->{$_} }
             @{$unified_info{scripts}} ) );
